/* بيانات باب taamul: تُحمَّل عند أول فتح للقسم */
window.TAAMUL = {"ch":[{"id":"sidq","t":"الصدق والكلمة الطيبة والتثبّت","d":"الآيات التي تجعل الصدق والقول السديد والكلمة الحسنة أساس التعامل بين الناس، وتنهى عن قول الزور وعن بناء الأحكام على الخبر غير الموثوق."},{"id":"wafa","t":"الوفاء بالعهد والوعد وترك الخيانة","d":"الآيات التي تجعل الوفاء بالعهد والوعد مسؤولية أمام الله، وتنهى عن نقض الأيمان وعن مخالفة القول للفعل وعن الخيانة."},{"id":"adl","t":"العدل والشهادة والتعاون على الخير","d":"الآيات التي تأمر بالقيام بالقسط ولو على النفس والأقربين، وبأداء الشهادة دون كتمان، وبالعدل في القول، وبالتعاون على البر لا على الإثم."},{"id":"sulh","t":"الإصلاح والعفو والحلم","d":"الآيات التي ترغّب في الإصلاح بين الناس والعفو وكظم الغيظ، وفي دفع السيئة بالتي هي أحسن، وفي الحلم عند خطاب الجاهلين."},{"id":"adab","t":"الآداب الاجتماعية والجوار","d":"الآيات التي ترسم آداب العيش مع الناس: الجار والصاحب، ورد التحية، والاستئذان، وترك السخرية والغيبة والتجسس، وآداب المجالس والمشي والخلق."},{"id":"huquq","t":"حق المحتاج والإيثار والمعروف","d":"الآيات التي تبيّن حق السائل والمحتاج وحسن الرد عليه، وتنهى عن المنّ والأذى، وتمدح الإيثار، وتذم منع المعروف اليسير."}],"tp":[{"id":"sadiqin","ch":"sidq","t":"«وكونوا مع الصادقين»: الصدق منهج التعامل","e":"الأمر بالتقوى والكون مع الصادقين، والقول السديد في جميع الأحوال.","ay":[[9,119,119],[33,70,71]],"q":[{"bk":"saadi","s":9,"ay":119,"x":"قوموا بما يقتضيه الإيمانُ، وهو القيام بتقوى الله تعالى؛ باجتناب ما نهى الله عنه والبعد عنه، {وكونوا مع الصَّادقينَ}: في أقوالهم وأفعالهم وأحوالهم، الذين أقوالهم صدقٌ، وأعمالهم وأحوالهم لا تكون إلا صدقاً، خليَّةً من الكسل والفتور، سالمة من المقاصد السيئة، مشتملة على الإخلاص والنيَّة الصالحة؛ فإنَّ الصدق يهدي إلى البرِّ، وإنَّ البرَّ يهدي إلى الجنة؛ قال تعالى:{هذا يومُ ينفَعُ الصادقين صِدۡقُهم ...","w":"السعدي","en":"Al-Sa'di: stand by what faith requires, which is being mindful of Allah by avoiding what He forbade, and 'be with the truthful' in their words, deeds and states, whose words are truth and whose deeds and states are only truth, free of laziness and weakness, safe from bad intentions, and full of sincerity; for truthfulness leads to righteousness and righteousness leads to Paradise."},{"bk":"ibnkathir","s":9,"ay":119,"x":"وَعَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ: ﴿اتَّقُوا اللَّهَ وَكُونُوا مَعَ الصَّادِقِينَ﴾ مَعَ مُحَمَّدٍ ﷺ وَأَصْحَابِهِ.","w":"ابن كثير","en":"Ibn Kathir: from 'Abdullah ibn 'Umar: 'be mindful of Allah and be with the truthful' means with Muhammad, peace be upon him, and his companions."},{"bk":"saadi","s":33,"ay":70,"x":"يأمر تعالى المؤمنين بتقواه في جميع أحوالِهِم في السرِّ والعلانية، ويخصُّ منها ويندب للقول السديد، وهو القول الموافق للصواب أو المقارب له عند تعذُّر اليقين من قراءةٍ وذكرٍ وأمرٍ بمعروف ونهي عن منكر وتعلُّم علم وتعليمه والحرص على إصابة الصواب في المسائل العلميَّة وسلوك كلِّ طريق موصِل لذلك وكل وسيلةٍ تُعين عليه. ومن القول السديد لينُ الكلام ولطفُه في مخاطبة الأنام والقول المتضمِّن للنُّصح والإشارة بما هو الأصلح.","w":"السعدي","en":"Al-Sa'di: Allah commands the believers to be mindful of Him in all their states, in secret and in public, and singles out and recommends straight speech, which is speech in line with what is right or close to it when certainty is impossible, such as reading, remembrance, enjoining good, forbidding evil, and learning and teaching knowledge; and part of straight speech is gentleness and kindness of speech toward people and speech that carries sincere advice."}]},{"id":"qawlhasan","ch":"sidq","t":"«وقولوا للناس حسناً»: الكلمة الطيبة","e":"الأمر بالقول الحسن للناس عموماً، وبقول التي هي أحسن بين العباد.","ay":[[2,83,83],[17,53,53]],"q":[{"bk":"saadi","s":2,"ay":83,"x":"ثم أمر بالإحسان إلى الناس عموماً فقال:{وقولوا للناس حسناً}؛ ومن القول الحسن أمرهم بالمعروف ونهيهم عن المنكر وتعليمهم العلم وبذل السلام والبشاشة وغير ذلك من كل كلام طيب، ولما كان الإنسان لا يسع الناس بماله أُمر بأمر يقدر به على الإحسان إلى كل مخلوق وهو الإحسان بالقول، فيكون في ضمن ذلك النهي عن الكلام القبيح للناس حتى للكفار، ولهذا قال تعالى:{ولا تجادلوا أهل الكتاب إلا بالتي هي أحسن}؛ ومن أدب الإنسان الذي أدب الله به عباده أن يكون الإنسان نزيهاً في أقواله وأفعاله، غير فاحش ولا بذيء ولا شاتم ولا مخاصم، بل يكون حسن الخلق واسع الحلم، مجاملاً لكلِّ أحد، صبوراً على ما يناله من أذى الخلق امتثالاً لأمر الله ورجاءً لثوابه.","w":"السعدي","en":"Al-Sa'di: Allah then commands kindness to people in general, 'and speak good to people'; good speech includes enjoining the right and forbidding the wrong, teaching knowledge, giving greetings and a cheerful face, and every pleasant word; since a person cannot reach everyone with his wealth he is told of something he can do for every creature, kindness in speech, which includes avoiding ugly speech toward people, even disbelievers; so a person should be clean in words and deeds, not foul, abusive, insulting or quarrelsome, but good in character, wide in forbearance, courteous to everyone, patient with the harm of people, obeying Allah's command and hoping for His reward."},{"bk":"saadi","s":17,"ay":53,"x":"وهذا من لطفِهِ بعباده؛ حيثُ أمرهم بأحسن الأخلاق والأعمال والأقوال الموجبة للسعادة في الدُّنيا والآخرة، فقال:{وقُلۡ لعبادي يقولوا التي هي أحسنُ}: وهذا أمرٌ بكلِّ كلام يقرِّب إلى الله؛ من قراءةٍ وذكرٍ وعلم وأمرٍ بمعروف ونهي عن منكرٍ وكلام حسنٍ لطيفٍ مع الخلق على اختلاف مراتبهم ومنازلهم، وأنه إذا دار الأمر بين أمرين حسنين؛ فإنَّه يؤمَر بإيثار أحسَنِهما إن لم يمكن الجمعُ بينَهما، والقول الحسنُ داعٍ لكلِّ خلقٍ جميل وعمل صالح؛ فإنَّ مَن مَلَكَ لسانه؛ مَلَكَ جميع أمره.","w":"السعدي","en":"Al-Sa'di: this is from Allah's kindness to His servants, ordering the best of character, deeds and speech, which lead to happiness in this world and the next; 'and say to My servants to say that which is best' covers every word that brings one nearer to Allah — recitation, remembrance, knowledge, enjoining good, forbidding evil, and gentle, kind speech with people of every rank; if two good options conflict, the better is preferred when both cannot be done; and good speech calls to every fine trait and good deed, for whoever controls his tongue controls all his affairs."}]},{"id":"zur","ch":"sidq","t":"اجتناب قول الزور وشهادة الزور","e":"ذكر قول الزور وشهادة الزور واجتنابها، وصفة من لا يحضر الباطل.","ay":[[22,30,30],[25,72,72]],"q":[{"bk":"saadi","s":22,"ay":30,"x":"ولكن الذي من رحمته بعباده أنْ حرَّمه عليهم ومَنَعَهم منه تزكيةً لهم وتطهيراً من الشرك به وقول الزور ، ولهذا قال:{فاجتنبوا الرجسَ}؛ أي: الخبث القذر {من الأوثانِ}؛ أي: الأنداد التي جعلتموها آلهةً مع الله؛ فإنَّها أكبرُ أنواع الرجس.","w":"السعدي","en":"Al-Sa'di: out of His mercy Allah forbade these things to them to purify them from associating partners with Him and from false speech, so 'avoid the filth of idols'; that is, the dirty impurity, the rivals they made gods with Allah, for those are the greatest kind of filth."},{"bk":"ibnkathir","s":25,"ay":72,"x":"وَقِيلَ: الْمُرَادُ بِقَوْلِهِ تَعَالَى: ﴿لَا يَشْهَدُونَ الزُّورَ﴾ أَيْ: شَهَادَةُ الزُّورِ، وَهِيَ الكذب متعمدا على غيره، كَمَا [ثَبَتَ] فِي الصَّحِيحَيْنِ عَنْ أَبِي بَكْرَة قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: \"أَلَا أُنَبِّئُكُمْ بأكْبر الْكَبَائِرِ\" ثَلَاثًا، قُلْنَا: بَلَى، يَا رَسُولَ اللَّهِ، قَالَ: \"الشِّرْكُ بِاللَّهِ، وَعُقُوقُ الْوَالِدَيْنِ\". وَكَانَ مُتَّكِئًا فَجَلَسَ، فَقَالَ: \"أَلَا وَقَوْلُ الزُّورِ، أَلَا وَشَهَادَةُ الزُّورِ [أَلَا وَقَوْلُ الزُّورِ وَشَهَادَةُ الزُّورِ] .","w":"ابن كثير","en":"Ibn Kathir: it was also said that 'they do not bear witness to falsehood' means false testimony, which is knowingly lying against someone, as reported in the two Sahihs from Abu Bakra: the Prophet, peace be upon him, said three times, 'Shall I not tell you of the greatest of major sins?' We said, 'Yes, O Messenger of Allah.' He said, 'Associating others with Allah and disobedience to parents.' He had been reclining and sat up, and said, 'And false speech, and false testimony.'"},{"bk":"qurtubi","s":25,"ay":72,"x":"فِيهِ مَسْأَلَتَانِ: الْأُولَى- قَوْلُهُ تَعَالَى: ﴿وَالَّذِينَ لَا يَشْهَدُونَ الزُّورَ﴾ أَيْ لَا يَحْضُرُونَ الْكَذِبَ وَالْبَاطِلَ وَلَا يُشَاهِدُونَهُ.","w":"القرطبي","en":"Al-Qurtubi: it contains two points. First: His words 'those who do not witness falsehood' mean they do not attend lies and falsehood, nor look on at them."}]},{"id":"tathabbut","ch":"sidq","t":"التثبّت في الخبر وعدم اتباع الظن","e":"الأمر بالتبيّن عند خبر الفاسق، والنهي عن اتباع ما لا علم به.","ay":[[49,6,6],[17,36,36]],"q":[{"bk":"saadi","s":49,"ay":6,"x":"وهذا أيضاً من الآداب التي على أولي الألباب التأدُّبُ بها واستعمالها، وهو أنه إذا أخبرهم فاسقٌ بنبأ؛ أي: خبرٍ: أن يتثبَّتوا في خبره، ولا يأخذوه مجرداً؛ فإن في ذلك خطراً كبيراً ووقوعاً في الإثم؛ فإنَّ خبره إذا جُعل بمنزلة خبر الصادق العدل؛ حكم بموجب ذلك ومقتضاه، فحصل من تلف النفوس والأموال بغير حقٍّ بسبب ذلك الخبر ما يكون سبباً للندامة، بل الواجبُ عند خبر الفاسق التثبُّت والتبيُّن؛ فإن دلَّت الدلائل والقرائن على صدقه؛ عُمِلَ به وصُدِّق، وإن دلت على كذبه؛ كذِّب ولم يعمل به؛ ففيه دليل على أن خبر الصادق مقبول، وخبر الكاذب مردود، وخبر الفاسق متوقَّف فيه ، ولهذا كان السلف يقبلون روايات كثير من الخوارج المعروفين بالصدق، ولو كانوا فساقاً.","w":"السعدي","en":"Al-Sa'di: this is also among the manners that people of understanding must practise: when a wrongdoer brings news, they should verify it and not take it as it is, for there is great danger in that and a fall into sin; if his report were treated like that of a truthful, upright person, a ruling would follow from it, and lives and wealth could be lost unjustly because of that report, leading to regret; rather it is obligatory to verify and clarify; if the evidence points to his truth it is acted on, and if it points to his lying it is rejected; so the report of a truthful person is accepted, a liar's is rejected, and a wrongdoer's is held in suspense."},{"bk":"saadi","s":17,"ay":36,"x":"أي: ولا تتَّبع ما ليس لك به علم، بل تثبَّت في كلِّ ما تقوله وتفعله؛ فلا تظنَّ ذلك يذهب لا لك ولا عليك.","w":"السعدي","en":"Al-Sa'di: do not follow what you have no knowledge of; rather verify everything you say and do, and do not think that will pass without a reckoning, for you or against you."}]},{"id":"ahd","ch":"wafa","t":"الوفاء بالعهد: «إن العهد كان مسؤولاً»","e":"كون العهد مسؤولاً عنه، والأمر بالوفاء بعهد الله وبالعهود بين الناس.","ay":[[17,34,34],[16,91,91]],"q":[{"bk":"saadi","s":17,"ay":34,"x":"أي: مسؤولين عن الوفاء به وعدمه؛ فإن وفيتم؛ فلكم الثواب الجزيل، وإن لم تفعلوا ؛ فعليكم الإثم العظيم.","w":"السعدي","en":"Al-Sa'di: 'the covenant will be asked about' means people will be asked whether they kept it or not; if you keep it, you have the great reward, and if you do not, you bear the great sin."},{"bk":"saadi","s":16,"ay":91,"x":"وهذا يشمَلُ جميع ما عاهد العبدُ عليه ربَّه من العبادات والنذور والأيمان التي عقدها إذا كان الوفاء بها برًّا، ويشمل أيضاً ما تعاقد عليه هو وغيره؛ كالعهود بين المتعاقدين، وكالوعد الذي يعده العبدُ لغيره ويؤكِّده على نفسه؛ فعليه في جميع ذلك الوفاء وتتميمها مع القدرة، ولهذا نهى الله عن نقضِها، فقال:{ولا تنقُضوا الأيمان بعد توكيدها}: بعقدها على اسم الله تعالى.","w":"السعدي","en":"Al-Sa'di: this covers all that a servant has pledged to his Lord of acts of worship, vows and oaths he has sworn, if keeping them is righteousness; it also covers what he has agreed with others, like covenants between contracting parties and the promise a person gives and binds himself to; in all of that he must keep and complete it when able, and that is why Allah forbade breaking them: 'do not break oaths after confirming them'."}]},{"id":"naqd","ch":"wafa","t":"نقض العهد واتخاذ الأيمان دخلاً بين الناس","e":"النهي عن نقض الأيمان والعهود وضرب المثل لناقضها، وعن اتخاذ الأيمان خديعة.","ay":[[16,92,94]],"q":[{"bk":"saadi","s":16,"ay":92,"x":"{ولا تكونوا}: في نقضِكُم للعهودِ بأسوأ الأمثال وأقبحها وأدلِّها على سفه متعاطيها، وذلك {كالتي} تَغْزِلُ غزلاً قويًّا؛ فإذا استحكم وتمَّ ما أريد منه؛ نَقَضَتْه فجعلتْه {أنۡكاثاً}: فتعبت على الغزل، ثم على النقض، ولم تستفدْ سوى الخيبة والعناء وسفاهة العقل ونقص الرأي؛ فكذلك مَنْ نَقَضَ ما عاهد عليه؛ فهو ظالمٌ جاهلٌ سفيهٌ ناقص الدين والمروءة.","w":"السعدي","en":"Al-Sa'di: 'do not be' in your breaking of covenants like the worst, ugliest parable, the one that best shows the foolishness of whoever does it, like the woman who spins strong thread and, when it is finished, unravels it into pieces; she tires herself spinning and then unravelling and gains only disappointment and toil, with foolishness and a weak mind; so too whoever breaks what he has pledged is a wrongdoer, ignorant, foolish and lacking in religion and manliness."},{"bk":"ibnkathir","s":16,"ay":92,"x":"وَقَوْلُهُ: ﴿وَلا تَكُونُوا كَالَّتِي نَقَضَتْ غَزْلَهَا مِنْ بَعْدِ قُوَّةٍ أَنْكَاثًا﴾ قَالَ عَبْدُ اللَّهِ بْنُ كَثِيرٍ، وَالسُّدِّيُّ: هَذِهِ امْرَأَةٌ خَرْقَاءُ كَانَتْ بِمَكَّةَ، كُلَمَّا غَزَلَتْ شَيْئًا نَقَضَتْهُ بَعْدَ إِبْرَامِهِ.","w":"ابن كثير","en":"Ibn Kathir: His words 'and do not be like she who unravelled her spun thread after it was strong' — 'Abdullah ibn Kathir and al-Suddi said: this was a foolish woman in Makkah who, whenever she spun something, unravelled it after it was firm."}]},{"id":"maqt","ch":"wafa","t":"«كبر مقتاً عند الله أن تقولوا ما لا تفعلون»","e":"الإنكار على من يقول ما لا يفعل، وذكر صدق الوعد في إسماعيل عليه السلام.","ay":[[61,2,3],[19,54,54]],"q":[{"bk":"saadi","s":61,"ay":2,"x":"{يا أيُّها الذين آمنوا لم تقولونَ ما لا تفعلونَ}؛ أي: لم تقولونَ الخير وتحثُّون عليه، وربما تمدَّحتم به وأنتم لا تفعلونه، وتَنْهَوْنَ عن الشرِّ، وربَّما نزَّهتم أنفسكم عنه وأنتم متلوِّثون متَّصفون به؛ فهل تليقُ بالمؤمنين هذه الحالة الذَّميمة؟!","w":"السعدي","en":"Al-Sa'di: 'O you who believe, why do you say what you do not do?' means: why do you speak of good and urge it, and perhaps boast of it while you do not do it, and forbid evil, and perhaps keep yourselves clear of it while you are stained with it; does this blameworthy state befit believers?"},{"bk":"saadi","s":19,"ay":54,"x":"أي: لا يَعِدُ وعداً إلاَّ وَفَّى به، وهذا شاملٌ للوعد الذي يعقده مع الله أو مع العباد، ولهذا لما وعد من نفسِهِ الصبرَ على ذبح أبيه له؛ قال:{سَتَجِدني إن شاءَ الله من الصابرين}: وفَّى بذلك، ومكَّن أباه من الذبح الذي هو أكبر مصيبةٍ تصيبُ الإنسان.","w":"السعدي","en":"Al-Sa'di: 'true to his promise' means he never promised a promise without fulfilling it, and this includes the promise made to Allah or to people; so when he promised himself to be patient with being slaughtered by his father, he said, 'you will find me, if Allah wills, among the patient', and he fulfilled it and let his father proceed with the slaughter, the greatest calamity that can befall a person."}]},{"id":"khiyana","ch":"wafa","t":"النهي عن الخيانة ونبذ العهد على سواء","e":"النهي عن خيانة الله والرسول والأمانات، وأمر من خاف خيانة قوم بإعلامهم بنبذ العهد.","ay":[[8,27,27],[8,58,58]],"q":[{"bk":"saadi","s":8,"ay":27,"x":"يأمر تعالى عباده المؤمنين أن يؤدُّوا ما ائتمنهم الله عليه من أوامره ونواهيه؛ فإنَّ الأمانة قد عرضها الله على السماوات والأرض والجبال فأبَيْنَ أن يَحْمِلْنها وأشفَقْنَ منها وحملها الإنسانُ إنَّه كان ظلوماً جهولاً؛ فمن أدَّى الأمانة؛ استحقَّ من الله الثواب الجزيل، ومن لم يؤدِّها، بل خانها؛ استحقَّ العقاب الوبيل، وصار خائناً لله وللرسول ولأمانته، منقصاً لنفسه بكونه اتَّصفت نفسه بأخس الصفات وأقبح الشيات، وهو الخيانة، مفوتاً لها أكمل الصفات وأتمها، وهي الأمانة.","w":"السعدي","en":"Al-Sa'di: Allah commands the believers to fulfil what He entrusted them with of His commands and prohibitions, for the trust was offered to the heavens, the earth and the mountains and they refused to bear it and feared it, and man bore it; whoever fulfils the trust deserves a great reward, and whoever does not but betrays it deserves a grievous punishment and becomes a betrayer of Allah, the Messenger and his own trust, lowering himself by taking the vilest qualities, betrayal, and missing the most perfect quality, trustworthiness."},{"bk":"ibnkathir","s":8,"ay":58,"x":"يَقُولُ تَعَالَى لِنَبِيِّهِ، صَلَوَاتُ اللَّهِ وَسَلَامُهُ عَلَيْهِ ﴿وَإِمَّا تَخَافَنَّ مِنْ قَوْمٍ﴾ قَدْ عَاهَدْتَهُمْ ﴿خِيَانَةً﴾ أَيْ: نَقْضًا لِمَا بَيْنَكَ وَبَيْنَهُمْ مِنَ الْمَوَاثِيقِ وَالْعُهُودِ، ﴿فَانْبِذْ إِلَيْهِمْ﴾ أَيْ: عَهْدَهُمْ ﴿عَلَى سَوَاءٍ﴾ أَيْ: أَعْلِمْهُمْ بِأَنَّكَ قَدْ نَقَضْتَ عَهْدَهُمْ حَتَّى يَبْقَى عِلْمُكَ وَعِلْمُهُمْ بِأَنَّكَ حَرْبٌ لَهُمْ، وَهُمْ حَرْبٌ لَكَ، وَأَنَّهُ لَا عَهْدَ بَيْنَكَ وَبَيْنَهُمْ عَلَى السَّوَاءِ، أَيْ: تَسْتَوِي أَنْتَ وَهُمْ فِي ذَلِكَ …","w":"ابن كثير","en":"Ibn Kathir: Allah says to His Prophet, peace be upon him: 'if you fear betrayal from a people' with whom you made a pact, that is, a breaking of the covenants and agreements between you and them, 'then cast it back to them' — their covenant — 'equally', that is, let them know you have ended their covenant so that your knowledge and theirs are the same, that you are at war with them and they with you, and there is no covenant between you, on equal terms, so that you and they are alike in that …"}]},{"id":"qist","ch":"adl","t":"«كونوا قوّامين بالقسط» ولو على أنفسكم","e":"الأمر بالقيام بالقسط والشهادة لله ولو على النفس والأقربين، وعدم ترك العدل بسبب بغض قوم.","ay":[[4,135,135],[5,8,8]],"q":[{"bk":"saadi","s":4,"ay":135,"x":"يأمر تعالى عبادَه المؤمنين أن يكونوا {قوَّامين بالقسطِ شهداء لله}، والقوَّام صيغةُ مبالغةٍ؛ أي: كونوا في كلِّ أحوالكم قائمين بالقسطِ الذي هو العدل في حقوق الله وحقوق عباده؛ فالقِسْطُ في حقوق الله أن لا يُستعان بنعمه على معصيتِهِ، بل تُصرف في طاعته، والقِسْط في حقوق الآدميِّين أن تُؤدِّيَ جميع الحقوق التي عليك كما تَطْلُبُ حقوقك، فتؤدِّي النفقات الواجبة والدُّيون وتعامل الناس بما تحبُّ أن يعاملوك به من الأخلاق والمكافأة وغير ذلك. ومن أعظم أنواع القِسْط القِسْط في المقالات والقائلين؛ فلا يحكم لأحدِ القولين أو أحد المتنازِعَين لانتسابه أو ميله لأحدهما، بل يَجعل وجهته العدل بينهما، ومن القسط أداء الشهادة التي عندك على أيِّ وجه كان، حتى على الأحباب، بل على النفس، ولهذا قال:{شهداء لله ولو على أنفسكم أو الوالدين والأقربين …","w":"السعدي","en":"Al-Sa'di: Allah commands His believing servants to be 'upholders of justice, witnesses for Allah'; the word is an intensive form, so be in every state upholders of justice in Allah's rights and His servants' rights; justice in Allah's rights is not to use His blessings to disobey Him but to spend them in obeying Him; and in people's rights it is that you give all that is due from you as you ask for what is due to you, paying obligatory expenses and debts, and treating people as you would like them to treat you in character and in repayment; and among the greatest kinds of justice is justice in sayings and those who say them, so one does not rule for one of two sides because of kinship or leaning, but makes justice between them his aim; and part of justice is giving the testimony you hold in any case, even against loved ones and against yourself, which is why He said, 'witnesses for Allah, even against yourselves or parents and relatives' …"},{"bk":"saadi","s":5,"ay":8,"x":"أي: يحملنَّكم بغض قوم {على أن لا تَعۡدِلوا}؛ كما يفعله مَن لا عدل عنده ولا قِسْط، بل كما تشهدون لوليِّكم؛ فاشهدوا عليه، وكما تشهدون على عدوِّكم؛ فاشهدوا له، ولو كان كافراً أو مبتدعاً؛ فإنَّه يجب العدل فيه وقبول ما يأتي به من الحقِّ؛ [لأنه حقٌّ]، لا لأنه قاله، ولا يُرَدُّ الحق لأجل قوله؛ فإن هذا ظلم للحقِّ.","w":"السعدي","en":"Al-Sa'di: 'let not hatred of a people lead you to be unjust', as someone with no justice or fairness would do; but just as you witness for your friend, witness against him, and as you witness against your enemy, witness for him, even if he is a disbeliever or an innovator; for justice toward him is obligatory, and what truth he brings is accepted because it is truth, not because of who said it, and the truth is not rejected because of its speaker; that would be an injustice to the truth."}]},{"id":"shahada","ch":"adl","t":"أداء الشهادة وتحريم كتمانها","e":"الأمر بإقامة الشهادة لله، والنهي عن كتمانها.","ay":[[65,2,2],[2,283,283]],"q":[{"bk":"ibnkathir","s":65,"ay":2,"x":"وَقَوْلُهُ: ﴿ذَلِكُمْ يُوعَظُ بِهِ مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ﴾ أَيْ: هَذَا الَّذِي أَمَرْنَاكُمْ بِهِ مِنَ الْإِشْهَادِ وَإِقَامَةِ الشَّهَادَةِ، إِنَّمَا يَأْتَمِرُ بِهِ مَنْ يُؤْمِنُ بِاللَّهِ وَأَنَّهُ شَرَّعَ هَذَا، وَمَنْ يَخَافُ عِقَابَ اللَّهِ في الدار الآخرة.","w":"ابن كثير","en":"Ibn Kathir: His words 'that is an admonition for whoever believes in Allah and the Last Day' mean: what we have commanded you of taking witnesses and giving testimony is carried out only by one who believes in Allah and that He legislated this, and who fears Allah's punishment in the Hereafter."},{"bk":"qurtubi","s":65,"ay":2,"x":"السَّادِسَةُ- قَوْلُهُ تَعَالَى: ﴿وَأَقِيمُوا الشَّهادَةَ لِلَّهِ﴾ أَيْ تَقَرُّبًا إِلَى اللَّهِ فِي إِقَامَةِ الشَّهَادَةِ عَلَى وَجْهِهَا، إِذَا مَسَّتِ الْحَاجَةُ إِلَيْهَا مِنْ غَيْرِ تَبْدِيلٍ وَلَا تَغْيِيرٍ.","w":"القرطبي","en":"Al-Qurtubi: the sixth point: His words 'and establish the testimony for Allah' mean: seeking nearness to Allah by giving testimony in its proper form when it is needed, without alteration or change."},{"bk":"ibnkathir","s":2,"ay":283,"x":"وَقَوْلُهُ: ﴿وَلا تَكْتُمُوا الشَّهَادَة﴾ أَيْ: لَا تُخْفُوهَا وَتَغُلُّوهَا وَلَا تُظْهِرُوهَا. قَالَ ابْنُ عَبَّاسٍ وَغَيْرُهُ: شَهَادَةُ الزُّورِ مِنْ أَكْبَرِ الْكَبَائِرِ، وَكِتْمَانُهَا كَذَلِكَ.","w":"ابن كثير","en":"Ibn Kathir: His words 'and do not conceal testimony' mean do not hide it or conceal it or fail to bring it out. Ibn 'Abbas and others said: false testimony is among the greatest major sins, and concealing it is the same."}]},{"id":"adlqawl","ch":"adl","t":"العدل في القول والحكم","e":"الأمر بالعدل في القول ولو على قريب، وجمع الآية الأمر بالعدل والإحسان.","ay":[[6,152,152],[16,90,90]],"q":[{"bk":"ibnkathir","s":6,"ay":152,"x":"وَقَوْلُهُ: ﴿وَإِذَا قُلْتُمْ فَاعْدِلُوا وَلَوْ كَانَ ذَا قُرْبَى﴾ كَمَا قَالَ تَعَالَى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا كُونُوا قَوَّامِينَ بِالْقِسْطِ شُهَدَاءَ لِلَّهِ [وَلَوْ عَلَى أَنْفُسِكُمْ] ﴾ [الْمَائِدَةِ:٨] ، وَكَذَا الَّتِي تُشْبِهُهَا فِي سُورَةِ النِّسَاءِ [الْآيَةِ:١٣٥] ، يَأْمُرُ تَعَالَى بِالْعَدْلِ فِي الْفِعَالِ وَالْمَقَالِ، عَلَى الْقَرِيبِ وَالْبَعِيدِ، وَاللَّهُ تَعَالَى يَأْمُرُ بِالْعَدْلِ لِكُلِّ أَحَدٍ، فِي كُلِّ وَقْتٍ، وَفِي كُلِّ حَالٍ.","w":"ابن كثير","en":"Ibn Kathir: His words 'and when you speak, be just, even if it concerns a relative', as He said, 'O you who believe, be upholders of justice, witnesses for Allah, even against yourselves' (al-Ma'ida 8), and the similar verse in al-Nisa' (135): He commands justice in deeds and words, toward near and far; Allah commands justice for everyone, at every time and in every state."},{"bk":"saadi","s":16,"ay":90,"x":"فالعدل الذي أمر الله به يشملُ العدلَ في حقِّه وفي حقِّ عباده؛ فالعدلُ في ذلك أداءُ الحقوق كاملةً موفورةً؛ بأن يؤدِّيَ العبد ما أوجب الله عليه من الحقوق الماليَّة والبدنيَّة والمركَّبة منهما في حقِّه وحقِّ عباده، ويعامل الخلق بالعدل التامِّ، فيؤدِّي كلُّ والٍ ما عليه تحت ولايتِهِ، سواء في ذلك ولاية الإمامة الكبرى وولاية القضاء ونواب الخليفة ونواب القاضي.","w":"السعدي","en":"Al-Sa'di: the justice Allah commanded covers justice in His right and in His servants' rights; justice there is giving rights completely and fully, so that a servant performs what Allah obliged of financial, bodily and mixed rights in His right and his fellow servants' right, and deals with people with perfect justice, so every ruler fulfils what he owes within his authority, whether the greatest leadership, judgeship, the caliph's deputies or the judge's deputies."}]},{"id":"taawun","ch":"adl","t":"التعاون على البر والتقوى لا على الإثم والعدوان","e":"الأمر بالتعاون على فعل الخير وترك المنكر، والنهي عن التعاون على الإثم والعدوان.","ay":[[5,2,2]],"q":[{"bk":"saadi","s":5,"ay":2,"x":"{وتعاوَنوا على البِرِّ والتَّقوى}؛ أي: ليُعِنْ بعضكم بعضاً على البرِّ، وهو اسم جامع لكل ما يحبُّه الله ويرضاه من الأعمال الظاهرة والباطنة من حقوق الله وحقوق الآدميين، والتقوى في هذا الموضع اسم جامع لِتَرْكِ كلِّ ما يكرهه الله ورسوله من الأعمال الظاهرة والباطنة، وكل خصلة من خصال الخير المأمور بفعلها، أو خصلةٍ من خصال الشرِّ المأمور بتركها؛ فإن العبد مأمورٌ بفعلها بنفسه وبمعاونة غيره من إخوانه المؤمنين عليها بكلِّ قول يَبعث عليها وينشِّطُ لها وبكل فعل كذلك.","w":"السعدي","en":"Al-Sa'di: 'cooperate in righteousness and piety' means help one another in righteousness, which is a comprehensive word for everything Allah loves and approves of among outward and inward deeds, of Allah's rights and people's rights; and piety here is a comprehensive word for leaving all that Allah and His Messenger dislike, outward and inward; every good trait commanded, and every evil trait commanded to be left, a servant must do himself and with the help of his believing brothers, by every word that calls to it and encourages it and every deed likewise."},{"bk":"ibnkathir","s":5,"ay":2,"x":"وَقَوْلُهُ: ﴿وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلا تَعَاوَنُوا عَلَى الإثْمِ وَالْعُدْوَانِ﴾ يَأْمُرُ تَعَالَى عِبَادَهُ الْمُؤْمِنِينَ بِالْمُعَاوَنَةِ عَلَى فِعْلِ الْخَيْرَاتِ، وَهُوَ الْبَرُّ، وَتَرْكِ الْمُنْكِرَاتِ وَهُوَ التَّقْوَى، وَيَنْهَاهُمْ عَنِ التناصر على الباطل.","w":"ابن كثير","en":"Ibn Kathir: His words 'cooperate in righteousness and piety, and do not cooperate in sin and aggression': Allah commands His believing servants to cooperate in doing good, which is righteousness, and in leaving evil, which is piety, and forbids them to support one another in falsehood."}]},{"id":"islah","ch":"sulh","t":"الإصلاح بين الناس","e":"الإصلاح بين الناس من أبواب الخير في النجوى، وأخوّة المؤمنين وإصلاح ذات البين.","ay":[[4,114,114],[49,9,10]],"q":[{"bk":"saadi","s":4,"ay":114,"x":"أي: لا خير في كثير مما يتناجى به الناس ويتخاطبون، وإذا لم يكنْ فيه خيرٌ؛ فإمّا لا فائدة فيه؛ كفضول الكلام المباح، وإما شرٌّ ومضرَّة محضةٌ؛ كالكلام المحرَّم بجميع أنواعه.","w":"السعدي","en":"Al-Sa'di: there is no good in most of what people whisper about and talk of; and when there is no good in it, it is either of no benefit, like excess permissible talk, or pure evil and harm, like all kinds of forbidden talk."},{"bk":"saadi","s":49,"ay":10,"x":"{إنَّما المؤمنونَ إخوةٌ}: هذا عقدٌ عقدَه الله بين المؤمنين؛ أنَّه إذا وجد من أيِّ شخصٍ كان في مشرق الأرض ومغربها الإيمانُ بالله وملائكته وكتبه ورسله واليوم الآخر؛ فإنَّه أخٌ للمؤمنين أخوَّةً توجبُ أن يحبَّ له المؤمنون ما يحبُّون لأنفسهم، ويكرهوا له ما يكرهون لأنفسهم، ولهذا قال النبيُّ - صلى الله عليه وسلم - آمراً بالأخوَّة الإيمانيَّة:«لا تَحاسدوا ولا تَناجشوا ولا تَباغضوا ولا تَدابروا، وكونوا عبادَ اللهِ إخواناً","w":"السعدي","en":"Al-Sa'di: 'the believers are but brothers' is a bond Allah tied among the believers: whoever anywhere in the east or west has faith in Allah, His angels, books, messengers and the Last Day is a brother of the believers, a brotherhood that requires believers to love for him what they love for themselves and dislike for him what they dislike for themselves; so the Prophet, peace be upon him, commanded faith-brotherhood: 'Do not envy one another, do not outbid one another to inflate prices, do not hate one another, do not turn away from one another, and be servants of Allah, brothers' …"}]},{"id":"afw","ch":"sulh","t":"العفو والصفح وكظم الغيظ","e":"مراتب جزاء المسيء: العدل والفضل، ووصف المتقين بكظم الغيظ والعفو، والأمر بأخذ العفو.","ay":[[42,40,40],[3,134,134],[7,199,199]],"q":[{"bk":"saadi","s":42,"ay":40,"x":"ومرتبةُ الفضل: العفو والإصلاحُ عن المسيء، ولهذا قال:{فمَنۡ عفا وأصلَحَ فأجرُهُ على الله}؛ يجزيه أجراً عظيماً وثواباً كثيراً، وشَرَطَ الله في العفو الإصلاح فيه ليدلَّ ذلك على أنَّه إذا كان الجاني لا يَليقُ بالعفوِ عنه، وكانت المصلحةُ الشرعيةُ تقتضي عقوبتَه؛ فإنَّه في هذه الحال لا يكون مأموراً به، وفي جعل أجرِ العافي على الله مما يهيجُ على العفوِ وأنْ يعامِلَ العبدُ الخَلْقَ بما يحبُّ أن يعامِلَه الله به؛ فكما يحبُّ أن يعفوَ الله عنه؛ فليعفُ عنهم، وكما يحبُّ أن يسامِحَه الله؛ فليسامِحْهم؛ فإنَّ الجزاء من جنس العمل.","w":"السعدي","en":"Al-Sa'di: the level of grace is pardon and reconciliation toward the wrongdoer, so He said, 'whoever pardons and makes peace, his reward is with Allah'; He gives him a great reward; and Allah made reconciliation a condition of pardon to show that if the offender is not fit for pardon and the lawful interest requires punishing him, pardon is not commanded then; and making the pardoner's reward Allah's stirs people to pardon and to treat people as they want Allah to treat them: as you want Allah to pardon you, pardon them, and as you want Allah to overlook, overlook them, for reward matches deeds."},{"bk":"saadi","s":3,"ay":134,"x":"ثم وصف المتقين وأعمالهم فقال: {الذين ينفقون في السراء والضراء}؛ أي: في حال عسرهم ويسرهم إن أيسروا أكثروا من النفقة وإن أعسروا لم يحتقروا من المعروف شيئاً ولو قل، {والكاظمين الغيظ}: أي: إذا حصل لهم من غيرهم أذية توجب غيظهم، وهو امتلاء قلوبهم من الحنق الموجب للانتقام بالقول والفعل.","w":"السعدي","en":"Al-Sa'di: He then described the God-fearing and their deeds: 'those who spend in ease and hardship', that is, in their hardship and ease; if they become well off they spend much, and if poor they do not belittle any kindness however small; 'and those who restrain anger', that is, when they receive harm from others that provokes their anger, which is the filling of their hearts with rage that urges revenge in word and deed."},{"bk":"saadi","s":7,"ay":199,"x":"هذه الآية جامعة لِحُسْنِ الخلق مع الناس وما ينبغي في معاملتهم: فالذي ينبغي أن يعامَلَ به الناس: أن يأخذَ العفوَ؛ أي: ما سمحتْ به أنفسُهم وما سَهُلَ عليهم من الأعمال والأخلاق؛ فلا يكلِّفهم ما لا تسمح به طبائعهم، بل يشكُر من كلِّ أحدٍ ما قابله به من قول وفعل جميل أو ما هو دونَ ذلك، ويتجاوزُ عن تقصيرِهم ويغضُّ طرفه عن نقصهم ولا يتكبَّر على الصغير لصغره ولا ناقص العقل لنقصه ولا الفقير لفقره، بل يعامل الجميع باللُّطف والمقابلة بما تقتضيه الحال وتنشرح له صدورهم.","w":"السعدي","en":"Al-Sa'di: this verse gathers good character with people and what is fitting in dealing with them; what people should be dealt with is to 'take pardon', that is, what their souls give and what is easy for them of deeds and character, so one does not burden them with what their natures do not offer; rather one thanks everyone for any fine word or deed or less, overlooks their shortcomings, lowers the gaze toward their faults, is not proud toward the small for his smallness, nor the weak-minded for his weakness of mind, nor the poor for his poverty, but treats all with kindness and responds as the situation requires and as their hearts are put at ease."}]},{"id":"daf","ch":"sulh","t":"«ادفع بالتي هي أحسن»","e":"عدم استواء الحسنة والسيئة، والأمر بدفع السيئة بالتي هي أحسن.","ay":[[41,34,35],[23,96,96]],"q":[{"bk":"saadi","s":41,"ay":34,"x":"يقول تعالى: {ولا تَسۡتَوي الحسنةُ ولا السيئةُ}؛ أي: لا يستوي فعلُ الحسنات والطاعاتِ لأجل رضا الله تعالى ولا فعل السيئات والمعاصي التي تُسْخِطُه ولا تُرضيه، ولا يستوي الإحسانُ إلى الخلق ولا الإساءة إليهم لا في ذاتها ولا في وصفها ولا في جزائها.","w":"السعدي","en":"Al-Sa'di: Allah says: 'the good deed and the evil deed are not equal', that is, doing good deeds and acts of obedience for Allah's pleasure is not equal to doing evil and disobedience that anger Him, and kindness to people is not equal to harming them, neither in itself, nor in its description, nor in its reward."},{"bk":"ibnkathir","s":41,"ay":34,"x":"وَقَوْلُهُ: ﴿وَلا تَسْتَوِي الْحَسَنَةُ وَلا السَّيِّئَةُ﴾ أَيْ: فَرْقٌ عَظِيمٌ بَيْنَ هَذِهِ وَهَذِهِ، ﴿ادْفَعْ بِالَّتِي هِيَ أَحْسَنُ﴾ أَيْ: مَنْ أَسَاءَ إِلَيْكَ فَادْفَعْهُ عَنْكَ بِالْإِحْسَانِ إِلَيْهِ، كَمَا قَالَ عُمَرُ [رَضِيَ اللَّهُ عَنْهُ] مَا عَاقَبْتَ مَنْ عَصَى اللَّهَ فِيكَ بِمِثْلِ أَنْ تُطِيعَ اللَّهَ فِيهِ.","w":"ابن كثير","en":"Ibn Kathir: His words 'the good deed and the evil deed are not equal': there is a great difference between the two; 'repel evil with what is better', that is, whoever wrongs you, repel him from you with kindness toward him, as 'Umar, may Allah be pleased with him, said: you have not punished one who disobeyed Allah concerning you with anything like obeying Allah concerning him."}]},{"id":"hilm","ch":"sulh","t":"عباد الرحمن: «وإذا خاطبهم الجاهلون قالوا سلاماً»","e":"وصف عباد الرحمن بالمشي هوناً وقولهم سلاماً عند خطاب الجاهلين.","ay":[[25,63,63]],"q":[{"bk":"qurtubi","s":25,"ay":63,"x":"قَوْلُهُ تَعَالَى: ﴿هَوْناً﴾ الْهَوْنُ مَصْدَرُ الْهَيِّنِ وَهُوَ مِنَ السَّكِينَةِ وَالْوَقَارِ.","w":"القرطبي","en":"Al-Qurtubi: His words 'walking gently': hawn is the verbal noun of hayyin, and it comes from tranquillity and dignity."},{"bk":"ibnkathir","s":25,"ay":63,"x":"هَذِهِ صِفَاتُ عِبَادِ اللَّهِ الْمُؤْمِنِينَ ﴿الَّذِينَ يَمْشُونَ عَلَى الأرْضِ هَوْنًا﴾ أَيْ: بِسَكِينَةٍ وَوَقَارٍ مِنْ غَيْرِ جَبَرية وَلَا اسْتِكْبَارٍ، كَمَا قَالَ: ﴿وَلا تَمْشِ فِي الأرْضِ مَرَحًا إِنَّكَ لَنْ تَخْرِقَ الأرْضَ وَلَنْ تَبْلُغَ الْجِبَالَ طُولا﴾ [الْإِسْرَاءِ: ٣٧] .","w":"ابن كثير","en":"Ibn Kathir: these are the qualities of the believing servants of Allah, 'who walk upon the earth gently', that is, with tranquillity and dignity, without arrogance or pride, as He said, 'do not walk on the earth exultantly; you will never split the earth nor reach the mountains in height' (al-Isra' 37)."}]},{"id":"jar","ch":"adab","t":"الإحسان إلى الجار والصاحب","e":"الأمر بالإحسان إلى الجار القريب والجار البعيد والصاحب بالجنب.","ay":[[4,36,36]],"q":[{"bk":"saadi","s":4,"ay":36,"x":"أي: الجار القريب الذي له حقَّان؛ حقُّ الجوار وحقُّ القرابة؛ فله على جارِهِ حقٌّ وإحسانٌ راجعٌ إلى العرف.","w":"السعدي","en":"Al-Sa'di: 'the neighbour who is near' is the near neighbour who has two rights, the right of neighbourhood and the right of kinship; he has on his neighbour a right of kindness returning to what is customary."},{"bk":"ibnkathir","s":4,"ay":36,"x":"وَقَوْلُهُ: ﴿وَالْجَارِ ذِي الْقُرْبَى وَالْجَارِ الْجُنُبِ﴾ قَالَ عَلِيُّ بْنُ أَبِي طَلْحَةَ، عَنِ ابْنِ عَبَّاسٍ: ﴿وَالْجَارِ ذِي الْقُرْبَى﴾ يَعْنِي الَّذِي بَيْنَكَ وَبَيْنَهُ قَرَابَةٌ، ﴿وَالْجَارِ الْجُنُبِ﴾ الَّذِي لَيْسَ بَيْنَكَ وَبَيْنَهُ قُرَابَةٌ.","w":"ابن كثير","en":"Ibn Kathir: His words 'the neighbour who is near and the neighbour who is distant': 'Ali ibn Abi Talha reported from Ibn 'Abbas: 'the neighbour who is near' means the one between you and whom there is kinship, and 'the neighbour who is distant' is the one with whom you have no kinship."}]},{"id":"tahiyya","ch":"adab","t":"رد التحية بأحسن منها","e":"الأمر بردّ التحية بأحسن منها أو بمثلها.","ay":[[4,86,86]],"q":[{"bk":"saadi","s":4,"ay":86,"x":"التحية: هي اللفظ الصادر من أحد المتلاقيين على وجه الإكرام والدُّعاء وما يقترن بذلك اللفظ من البشاشة ونحوها، وأعلى أنواع التحية ما ورد به الشرعُ من السلام ابتداءً وردًّا، فأمر تعالى المؤمنين أنَّهم إذا حُيُّوا بأيِّ تحيَّة كانت أن يردُّوها بأحسن منها لفظاً وبشاشةً أو مثلها في ذلك، ومفهوم ذلك النهي عن عدم الردِّ بالكلِّيَّة أو رَدِّها بدونها. ويؤخذ من الآية الكريمة الحثُّ على ابتداء السلام والتحيَّة من وجهين: أحدهما: أنَّ الله أمر بردِّها بأحسنَ منها أو مثلِها، وذلك يستلزم أن التحيَّة مطلوبةٌ شرعاً.","w":"السعدي","en":"Al-Sa'di: a greeting is the word said by one of two who meet, in honour and prayer, with the cheerfulness that goes with it; the highest greeting is what the law brought, salam, first and in reply; so Allah commands the believers, when greeted with any greeting, to return it with a better one in wording and cheerfulness or the same; and the implied meaning is the prohibition of not replying at all or replying with less. From the verse one understands encouragement to begin with salam and greeting from two angles: first, Allah commanded returning it with a better or equal one, which implies that greeting is requested by the law."},{"bk":"ibnkathir","s":4,"ay":86,"x":"وَقَوْلُهُ: ﴿وَإِذَا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا﴾ أَيْ: إِذَا سَلَّمَ عَلَيْكُمُ الْمُسْلِمُ، فَرَدُّوا عَلَيْهِ أَفْضَلَ مِمَّا سَلَّمَ، أَوْ رَدُّوا عَلَيْهِ بِمِثْلِ مَا سَلَّمَ [بِهِ] فَالزِّيَادَةُ مَنْدُوبَةٌ، وَالْمُمَاثَلَةُ مَفْرُوضَةٌ.","w":"ابن كثير","en":"Ibn Kathir: His words 'when you are greeted with a greeting, greet with better or return it': if a Muslim greets you with salam, reply with more than he gave, or reply with the same as he gave; adding is recommended and matching is obligatory."}]},{"id":"istidhan","ch":"adab","t":"الاستئذان وآداب دخول البيوت","e":"النهي عن دخول بيوت الغير حتى الاستئناس والسلام، وآداب الدخول في بيت النبي ﷺ.","ay":[[24,27,29],[33,53,53]],"q":[{"bk":"saadi","s":24,"ay":27,"x":"هذا الحكم في البيوت المسكونة سواء كان فيها متاعٌ للإنسان أم لا، وفي البيوت غير المسكونة التي لا متاع فيها للإنسان، وأما البيوتُ التي ليس فيها أهلُها، وفيها متاعُ الإنسان المحتاج للدخول إليه، وليس فيها أحدٌ يتمكَّن من استئذانه، وذلك كبيوت الكراء وغيرها؛ فقد ذكرها بقوله:{ليس عليكم جُناحٌ}؛ أي: حرجٌ وإثمٌ؛ دلَّ على أنَّ الدُّخول من غير استئذان في البيوت السابقة أنه محرَّم وفيه حرج {أن تدخُلوا بيوتاً غير مسكونةٍ فيها متاعٌ لكم}: وهذا من احترازاتِ القرآن العجيبةِ؛ فإنَّ قولَه:{لا تدخُلوا بيوتاً غير بيوتكم}: لفظٌ عامٌّ في كل بيت ليس ملكاً للإنسان، أخرج منه تعالى البيوتَ التي ليست ملكَه وفيها متاعُهُ وليس فيها ساكنٌ، فأسقط الحرج في الدُّخول إليها.","w":"السعدي","en":"Al-Sa'di: this ruling applies to inhabited houses whether or not they hold a person's belongings, and to uninhabited houses with no belongings of a person; as for houses whose people are absent but which hold a needy person's belongings and no one there can be asked, such as rented houses, He mentioned them in 'there is no blame on you', that is, no hardship or sin; which shows that entering without asking in the houses mentioned earlier is forbidden and a sin; 'to enter uninhabited houses in which is a benefit for you': this is one of the Quran's remarkable precisions, for 'do not enter houses other than your own' is a general expression covering every house not owned by a person, and He excluded houses not owned by him that hold his belongings and have no occupant, and removed the hardship of entering them."},{"bk":"qurtubi","s":24,"ay":27,"x":"الثَّالِثَةُ- مَدَّ اللَّهُ سُبْحَانَهُ وَتَعَالَى التَّحْرِيمَ فِي دُخُولِ بَيْتٍ لَيْسَ هُوَ بَيْتَكَ إِلَى غَايَةٍ هِيَ الِاسْتِئْنَاسُ، وَهُوَ الِاسْتِئْذَانُ.","w":"القرطبي","en":"Al-Qurtubi: the third point: Allah extended the prohibition of entering a house that is not yours up to a limit, which is isti'nas, that is, asking permission."},{"bk":"saadi","s":33,"ay":53,"x":"والمعنى: أنكم لا تدخُلوا بيوتَ النبيِّ إلاَّ بشرطين: الإذن لكم بالدخول، وأنْ يكون جلوسُكم بمقدارِ الحاجة، ولهذا قال:{ولكنۡ إذا دُعيتُم فادۡخُلوا فإذا طَعِمۡتُم فانتَشِروا ولا مُسۡتَأنِسينَ لحديثٍ}؛ أي: قبل الطعام وبعده.","w":"السعدي","en":"Al-Sa'di: the meaning is: do not enter the Prophet's houses except on two conditions: permission to enter, and that your sitting be only as long as needed; so He said, 'but when you are invited, enter, and when you have eaten, disperse, not lingering for conversation', that is, before the meal and after it."}]},{"id":"sukhriya","ch":"adab","t":"النهي عن السخرية والتنابز والغيبة والتجسس","e":"النهي عن السخرية واللمز والتنابز وسوء الظن والتجسس والغيبة.","ay":[[49,11,12]],"q":[{"bk":"saadi","s":49,"ay":11,"x":"وهذا أيضاً من حقوق المؤمنين بعضهم على بعض؛ أن:{لا يَسۡخَرۡ قومٌ من قومٍ}: بكلِّ كلامٍ وقولٍ وفعلٍ دالٍّ على تحقير الأخ المسلم؛ فإنَّ ذلك حرامٌ لا يجوز، وهو دالٌّ على إعجاب الساخر بنفسه، وعسى أن يكون المسخورُ به خيراً من الساخر، وهو الغالبُ والواقعُ؛ فإنَّ السخرية لا تقع إلاَّ من قلب ممتلئٍ من مساوئ الأخلاق، متحلٍّ بكل خلقٍ ذميمٍ، متخلٍّ من كلِّ خلقٍ كريم، ولهذا قال النبي - صلى الله عليه وسلم -: «بحسب امرئٍ من الشرِّ أن يحقر أخاه المسلمَ».","w":"السعدي","en":"Al-Sa'di: this too is among the believers' rights over one another: 'let not a people mock another people' by any word, speech or act that shows contempt of a Muslim brother; that is forbidden and not allowed, and it shows the mocker's self-admiration, and it may be that the one mocked is better than the mocker, which is the usual case and the reality, for mockery arises only from a heart full of bad character, adorned with every blameworthy trait and bare of every noble one; so the Prophet, peace be upon him, said: 'It is enough evil for a man that he looks down on his Muslim brother.'"},{"bk":"saadi","s":49,"ay":12,"x":"نهى تعالى عن كثيرٍ من الظَّنِّ السيِّئِ بالمؤمنين، {إنَّ بعضَ الظَّنِّ إثمٌ}: وذلك كالظَّنِّ الخالي من الحقيقة والقرينة، وكظنِّ السَّوْءِ الذي يقترن به كثيرٌ من الأقوال والأفعال المحرَّمة؛ فإنَّ بقاءَ ظنِّ السَّوْءِ بالقلب لا يقتصر صاحبه على مجرَّد ذلك، بل لا يزال به حتى يقول ما لا ينبغي ويفعل ما لا ينبغي، وفي ذلك أيضاً إساءةُ الظنِّ بالمسلم وبغضُهُ وعداوتُهُ المأمور بخلافها منه، {ولا تَجَسَّسوا}؛ أي: لا تفتِّشوا عن عورات المسلمين، ولا تَتَّبعوها، ودَعُوا المسلم على حاله، واستعملوا التغافُل عن زلاَّته، التي إذا فُتِّشَتْ؛ ظهرَ منها ما لا ينبغي، {ولا يَغۡتَب بعضُكُم بعضاً}: والغيبة كما قال النبي - صلى الله عليه وسلم -: «ذِكْرُكَ أخاك بما يكرَهُ، ولو كان فيه».","w":"السعدي","en":"Al-Sa'di: Allah forbade much ill thought toward believers: 'some suspicion is sin', like suspicion without truth or sign, and ill thought accompanied by forbidden words and deeds; for ill thought kept in the heart does not stop at that but leads its holder to say and do what he should not, and it also means thinking ill of a Muslim, hating and opposing him, which we are commanded the opposite of; 'and do not spy', that is, do not search for Muslims' faults or follow them, leave a Muslim as he is and feign unawareness of his slips, which, if searched for, would reveal what should not be; 'and do not backbite one another', and backbiting, as the Prophet, peace be upon him, said, is 'your mentioning your brother with what he dislikes, even if it is in him'."}]},{"id":"majlis","ch":"adab","t":"التفسح في المجالس","e":"الأمر بالتفسح في المجالس عند طلب ذلك، وجزاء من فسح.","ay":[[58,11,11]],"q":[{"bk":"saadi","s":58,"ay":11,"x":"هذا أدبٌ من الله لعباده [المؤمنين] إذا اجتمعوا في مجلس من مجالس مجتمعاتهم، واحتاجَ بعضُهم أو بعضُ القادمين [عليهم] للتفسُّح له في المجلس؛ فإنَّ من الأدب أن يَفْسَحوا له؛ تحصيلاً لهذا المقصود، وليس ذلك بضارٍّ للفاسح شيئاً، فيحصلُ مقصود أخيه من غير ضررٍ يلحقه، والجزاء من جنس العمل؛ فإنَّ من فَسَحَ؛ فَسَحَ الله له، ومن وسَّع لأخيه؛ وسَّع الله عليه، {وإذا قيل انشُزوا}؛ أي: ارتفعوا وتَنَحَّوْا عن مجالسكم لحاجةٍ تعرِضُ، {فانشُزوا}؛ أي: فبادروا للقيام لتحصيل تلك المصلحة؛ فإنَّ القيام بمثل هذه الأمور من العلم والإيمان، والله تعالى يرفع أهل العلم والإيمان درجاتٍ بحسب ما خصَّهم [اللَّه] به من العلم والإيمان.","w":"السعدي","en":"Al-Sa'di: this is a manner from Allah to His believing servants: when they gather in a meeting and some of them or newcomers need room made, it is part of good manners to make room for him to achieve this aim; it does not harm the one making room, while his brother's aim is met without harm to himself; and reward matches deeds, for whoever makes room, Allah makes room for him, and whoever gives his brother space, Allah gives him ease; 'and when it is said, rise up', that is, move away from your seats for a need that arises, 'then rise up', that is, hasten to rise to achieve that interest, for doing such things is part of knowledge and faith; and Allah raises people of knowledge and faith in ranks according to what He gave them of knowledge and faith."},{"bk":"ibnkathir","s":58,"ay":11,"x":"يَقُولُ تَعَالَى مُؤَدِّبًا عِبَادَهُ الْمُؤْمِنِينَ، وَآمِرًا لَهُمْ أَنْ يُحْسِنَ بَعْضُهُمْ إِلَى بَعْضٍ فِي الْمَجَالِسِ: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قِيلَ لَكُمْ تَفَسَّحُوا فِي الْمَجَالِسِ﴾ وَقُرِئَ ﴿فِي الْمَجْلِسِ﴾ ﴿فَافْسَحُوا يَفْسَحِ اللَّهُ لَكُمْ﴾ وَذَلِكَ أَنَّ الْجَزَاءَ مِنْ جِنْسِ الْعَمَلِ، كَمَا جَاءَ فِي الْحَدِيثِ الصَّحِيحِ: \"مَنْ بَنَى لِلَّهِ مَسْجِدًا بَنَى اللَّهُ لَهُ بَيْتًا فِي الْجَنَّةِ\" وَفِي الْحَدِيثِ الْآخَرِ: \"وَمَنْ يَسَّر عَلَى مُعْسِر يَسَّر اللَّهُ عَلَيْهِ فِي الدُّنْيَا وَالْآخِرَةِ، [وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللَّهُ فِي الدُّنْيَا وَالْآخِرَةِ] وَاللَّهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ\" وَلِهَذَا أَشْبَاهٌ كَثِيرَةٌ؛ وَلِهَذَا قَالَ: ﴿فَافْسَحُوا يَفْسَحِ اللَّهُ لَكُمْ﴾ .","w":"ابن كثير","en":"Ibn Kathir: Allah says, teaching His believing servants manners and commanding them to be kind to one another in gatherings: 'O you who believe, when it is said to you, make room in the gatherings', 'then make room; Allah will make room for you', because reward matches deeds, as in the sound hadith: 'Whoever builds a mosque for Allah, Allah builds for him a house in Paradise', and in another hadith: 'Whoever eases the hardship of one in difficulty, Allah eases for him in this world and the next; and whoever covers a Muslim, Allah covers him in this world and the next; and Allah helps the servant as long as the servant helps his brother'; and there are many like it; that is why He said: 'make room; Allah will make room for you'."}]},{"id":"luqman","ch":"adab","t":"وصية لقمان في الخلق: لا تصعّر خدك ولا تمش مرحاً","e":"وصية لقمان لابنه: ترك التكبر في الوجه والمشي، والاقتصاد في المشي وخفض الصوت.","ay":[[31,18,19]],"q":[{"bk":"saadi","s":31,"ay":18,"x":"{ولا تُصَعِّرۡ خدَّك للناس}؛ أي: لا تُمِلْهُ وتعبسْ بوجهك للناس تكبُّراً عليهم وتعاظماً، {ولا تَمۡشِ في الأرض مَرَحاً}؛ أي: بَطِراً فخراً بالنعم ناسياً المنعِم معجباً بنفسك.","w":"السعدي","en":"Al-Sa'di: 'do not turn your cheek away from people' means do not turn it aside or frown at people out of pride and superiority, 'and do not walk in the land exultantly' means with arrogance and boasting of blessings, forgetting the Giver of blessings and admiring yourself."},{"bk":"ibnkathir","s":31,"ay":18,"x":"وَقَوْلُهُ: ﴿وَلا تُصَعِّرْ خَدَّكَ لِلنَّاسِ﴾ يَقُولُ: لَا تُعرِضْ بِوَجْهِكَ عَنِ النَّاسِ إِذَا كَلَّمْتَهُمْ أَوْ كَلَّمُوكَ، احْتِقَارًا مِنْكَ لَهُمْ، وَاسْتِكْبَارًا عَلَيْهِمْ وَلَكِنْ ألِنْ جَانِبَكَ، وَابْسُطْ وَجْهَكَ إِلَيْهِمْ، كَمَا جَاءَ فِي الْحَدِيثِ: \"وَلَوْ أَنْ تَلْقَى أَخَاكَ وَوَجْهُكَ إِلَيْهِ مُنْبَسِط، وَإِيَّاكَ وَإِسْبَالَ الْإِزَارِ فَإِنَّهَا مِنَ المِخيلَة، وَالْمَخِيلَةُ لَا يُحِبُّهَا اللَّهَ\".","w":"ابن كثير","en":"Ibn Kathir: His words 'do not turn your cheek away from people' mean do not turn your face from people when you talk with them or they with you, out of contempt for them and pride; rather soften your side and put a cheerful face toward them, as in the hadith: 'even if you meet your brother with a cheerful face; and beware of letting your garment trail, for it comes from arrogance, and Allah does not love arrogance.'"}]},{"id":"sail","ch":"huquq","t":"حق السائل والمحتاج وحسن الرد","e":"النهي عن نهر السائل، والأمر بالقول المعروف والمغفرة وبيان أنهما خير من صدقة يتبعها أذى.","ay":[[93,9,10],[2,263,263]],"q":[{"bk":"saadi","s":93,"ay":10,"x":"ولهذا قال: {فأمَّا اليتيمَ فلا تَقۡهَرۡ}؛ أي: لا تُسِئْ معاملة اليتيم، ولا يَضِقْ صدرُك عليه، ولا تنهره، بل أكرمه، وأعطه ما تيسَّر، واصنع به كما تحبُّ أن يُصْنَعَ بولدك من بعدك، {وأمَّا السائلَ فلا تنهر}؛ أي: لا يصدر منك كلامٌ للسائل يقتضي ردَّه عن مطلوبه بنَهْرٍ وشراسةِ خلقٍ، بل أعطه ما تيسَّر عندك، أو ردَّه بمعروفٍ وإحسانٍ.","w":"السعدي","en":"Al-Sa'di: 'as for the orphan, do not oppress him', that is, do not treat him badly nor let your chest be tight with him nor rebuke him, but honour him, give what is easy, and do to him as you would like done to your own child after you; 'as for the one who asks, do not rebuke', that is, let no word come from you to the asker that turns him away from his request with rebuke and harshness, but give him what you easily can, or turn him away with kindness and good."},{"bk":"saadi","s":2,"ay":263,"x":"ذكر الله أربع مراتب للإحسان: المرتبة العليا: النفقة الصادرة عن نية صالحة ولم يتبعها المنفق منًّا ولا أذى. ثم يليها قول المعروف وهو الإحسان القولي بجميع وجوهه الذي فيه سرور المسلم، والاعتذار من السائل إذا لم يوافق عنده شيئاً، وغير ذلك من أقوال المعروف.","w":"السعدي","en":"Al-Sa'di: Allah mentioned four levels of kindness: the highest is spending from a good intention not followed by reproach or harm; next comes a kind word, which is kindness in speech in all its forms that brings joy to a Muslim, including apologising to the asker when one has nothing, and other kind words."}]},{"id":"mann","ch":"huquq","t":"إبطال الصدقة بالمنّ والأذى","e":"النهي عن إبطال الصدقة بالمنّ والأذى وبيان مثل ذلك.","ay":[[2,264,264]],"q":[{"bk":"saadi","s":2,"ay":264,"x":"وأما من أنفق لله ثم أتبع نفقته منًّا وأذى، أو عمل عملاً فأتى بمبطل لذلك العمل فهذا مثله مثال صاحب هذه الجنة، لكن سلط عليها {إعصار}؛ وهو الريح الشديدة {فيه نار فاحترقت}؛ وله ذرية ضعفاء وهو ضعيف قد أصابه الكبر، فهذه الحال من أفظع الأحوال، ولهذا صدَّر هذا المثل بقوله:{أيود أحدكم}؛ إلى آخرها بالاستفهام المتقرر عند المخاطبين فظاعته، فإن تَلَفَها دفعة واحدة بعد زهاء أشجارها وإيناع ثمارها مصيبة كبرى، ثم حصول هذه الفاجعة وصاحبها كبير قد ضعف عن العمل وله ذرية ضعفاء لا مساعدة منهم له ومؤنتهم عليه فاجعة أخرى، فصار صاحب هذا المثل الذي عمل لله ثم أبطل عمله بمنافٍ له يشبه حال صاحب الجنة التي جرى عليها ما جرى حين اشتدت ضرورته إليها.","w":"السعدي","en":"Al-Sa'di: whoever spent for Allah and then followed his spending with reproach and harm, or did a deed and then brought something that voids it, his likeness is that of the owner of this garden on which a hurricane was sent, a violent wind 'with fire in it', so it burned, and he had weak offspring and was himself weak with old age; this is among the most terrible states, so He opened this parable with the question 'would any of you like...', a question whose awfulness is settled for the audience; for its loss all at once after its trees had grown and its fruits ripened is a great calamity, and then this disaster befalling an old man too weak to work, with weak children who cannot help him and whom he must support, is another disaster …"},{"bk":"ibnkathir","s":2,"ay":264,"x":"ولهذا قال تعالى: ﴿يَاأَيُّهَا الَّذِينَ آمَنُوا لَا تُبْطِلُوا صَدَقَاتِكُمْ بِالْمَنِّ وَالأذَى﴾ فَأَخْبَرَ أَنَّ الصَّدَقَةَ تَبْطُلُ بِمَا يَتْبَعُهَا مِنَ الْمَنِّ وَالْأَذَى، فَمَا يَفِي ثَوَابَ الصَّدَقَةَ بِخَطِيئَةِ الْمَنِّ وَالْأَذَى.","w":"ابن كثير","en":"Ibn Kathir: that is why He said: 'O you who believe, do not nullify your charities with reproach and harm', informing that charity is nullified by the reproach and harm that follow it, so the reward of charity does not cover the sin of reproach and harm."}]},{"id":"ithar","ch":"huquq","t":"الإيثار: «ويؤثرون على أنفسهم»","e":"مدح الأنصار بحبهم من هاجر إليهم وإيثارهم على أنفسهم ولو كان بهم خصاصة.","ay":[[59,9,9]],"q":[{"bk":"saadi","s":59,"ay":9,"x":"وهذا يدلُّ على سلامة صدورهم وانتفاء الغلِّ والحقد والحسد عنها، ويدلُّ ذلك على أنَّ المهاجرين أفضل من الأنصار؛ لأنَّ الله قدَّمهم بالذِّكر، وأخبر أنَّ الأنصارَ لا يجدون في صدورهم حاجةً مما أوتوا، فدلَّ على أنَّ الله تعالى آتاهم ما لم يؤتِ الأنصارَ ولا غيرهم، ولأنَّهم جمعوا بين النصرة والهجرة، وقوله:{ويؤثِرونَ على أنفسِهِم ولو كان بهم خَصاصةٌ}؛ أي: ومن أوصاف الأنصار التي فاقوا بها غيرهم وتميَّزوا بها عمَّن سواهم الإيثار، وهو أكمل أنواع الجود، وهو الإيثار بمحابِّ النفس من الأموال وغيرها، وبذلها للغيرِ، مع الحاجة إليها، بل مع الضَّرورة والخَصاصة، وهذا لا يكون إلا من خُلُقٍ زكيٍّ ومحبَّة لله تعالى مقدَّمة على [محبة] شهوات النفس ولذَّاتها.","w":"السعدي","en":"Al-Sa'di: His words 'and they prefer others over themselves even if they are in need' mean: among the qualities of the Ansar by which they surpassed others is preferring others, which is the most perfect kind of generosity: giving up what the self loves of wealth and other things and giving it to others while in need of it, even in dire need and poverty; this arises only from a pure character and love of Allah placed before the desires and pleasures of the self."},{"bk":"ibnkathir","s":59,"ay":9,"x":"وَقَوْلُهُ: ﴿وَيُؤْثِرُونَ عَلَى أَنْفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ﴾ يَعْنِي: حَاجَةً، أَيْ: يُقَدِّمُونَ الْمَحَاوِيجَ عَلَى حَاجَةِ أَنْفُسِهِمْ، وَيَبْدَءُونَ بِالنَّاسِ قَبَلَهُمْ فِي حَالِ احْتِيَاجِهِمْ إِلَى ذَلِكَ.","w":"ابن كثير","en":"Ibn Kathir: His words 'and they prefer others over themselves even if they are in need' mean in need; that is, they put the needy ahead of their own need and begin with others before themselves while they themselves need it."}]},{"id":"maun","ch":"huquq","t":"منع الماعون وحق الناس في المعروف","e":"ذم الذين يمنعون الماعون، وهو ما جرت العادة ببذله من الأشياء اليسيرة.","ay":[[107,4,7]],"q":[{"bk":"saadi","s":107,"ay":7,"x":"ولهذا وصف الله هؤلاء بالرِّياء والقسوة وعدم الرحمة، فقال:{الذين هم يراؤون}؛ أي: يعملون الأعمال لأجل رئاء الناس، {ويمنعون الماعون}؛ أي: يمنعون إعطاء الشيء الذي لا يضرُّ إعطاؤه على وجه العارية أو الهبة؛ كالإناء والدَّلو والفأس ونحو ذلك ممَّا جرت العادة ببذله والسَّماح به ، فهؤلاء لشدَّة حرصهم يمنعون الماعون؛ فكيف بما هو أكثر منه؟!","w":"السعدي","en":"Al-Sa'di: Allah described these people with showing off, hardness and lack of mercy, saying 'those who show off and withhold small kindnesses'; that is, they withhold giving what does no harm to give, by loan or gift, like a vessel, a bucket, an axe and the like that people customarily lend and are generous with; so out of great stinginess they withhold the small thing; how then what is more than it?"},{"bk":"ibnkathir","s":107,"ay":7,"x":"وَقَوْلُهُ: ﴿وَيَمْنَعُونَ الْمَاعُونَ﴾ أَيْ: لَا أَحْسَنُوا عِبَادَةَ رَبِّهِمْ، وَلَا أَحْسَنُوا إِلَى خَلْقِهِ حَتَّى وَلَا بِإِعَارَةِ مَا يُنْتَفَعُ بِهِ وَيُسْتَعَانُ بِهِ، مَعَ بَقَاءِ عَيْنِهِ وَرُجُوعِهِ إِلَيْهِمْ.","w":"ابن كثير","en":"Ibn Kathir: His words 'and they withhold small kindnesses' mean: they did not worship their Lord well and did not do good to His creation, not even by lending what can be benefited from and used for help while its substance remains and returns to them."}]}],"ay":{"89":"وَإِذۡ أَخَذۡنَا مِيثَٰقَ بَنِيٓ إِسۡرَٰٓءِيلَ لَا تَعۡبُدُونَ إِلَّا ٱللَّهَ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَانٗا وَذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَقُولُواْ لِلنَّاسِ حُسۡنٗا وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ ثُمَّ تَوَلَّيۡتُمۡ إِلَّا قَلِيلٗا مِّنكُمۡ وَأَنتُم مُّعۡرِضُونَ","269":"۞ قَوۡلٞ مَّعۡرُوفٞ وَمَغۡفِرَةٌ خَيۡرٞ مِّن صَدَقَةٖ يَتۡبَعُهَآ أَذٗىۗ وَٱللَّهُ غَنِيٌّ حَلِيمٞ","270":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُبۡطِلُواْ صَدَقَٰتِكُم بِٱلۡمَنِّ وَٱلۡأَذَىٰ كَٱلَّذِي يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ وَلَا يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ فَمَثَلُهُۥ كَمَثَلِ صَفۡوَانٍ عَلَيۡهِ تُرَابٞ فَأَصَابَهُۥ وَابِلٞ فَتَرَكَهُۥ صَلۡدٗاۖ لَّا يَقۡدِرُونَ عَلَىٰ شَيۡءٖ مِّمَّا كَسَبُواْۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ","289":"۞ وَإِن كُنتُمۡ عَلَىٰ سَفَرٖ وَلَمۡ تَجِدُواْ كَاتِبٗا فَرِهَٰنٞ مَّقۡبُوضَةٞۖ فَإِنۡ أَمِنَ بَعۡضُكُم بَعۡضٗا فَلۡيُؤَدِّ ٱلَّذِي ٱؤۡتُمِنَ أَمَٰنَتَهُۥ وَلۡيَتَّقِ ٱللَّهَ رَبَّهُۥۗ وَلَا تَكۡتُمُواْ ٱلشَّهَٰدَةَۚ وَمَن يَكۡتُمۡهَا فَإِنَّهُۥٓ ءَاثِمٞ قَلۡبُهُۥۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ عَلِيمٞ","426":"ٱلَّذِينَ يُنفِقُونَ فِي ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلۡكَٰظِمِينَ ٱلۡغَيۡظَ وَٱلۡعَافِينَ عَنِ ٱلنَّاسِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ","528":"۞ وَٱعۡبُدُواْ ٱللَّهَ وَلَا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنٗا وَبِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱلۡجَارِ ذِي ٱلۡقُرۡبَىٰ وَٱلۡجَارِ ٱلۡجُنُبِ وَٱلصَّاحِبِ بِٱلۡجَنۢبِ وَٱبۡنِ ٱلسَّبِيلِ وَمَا مَلَكَتۡ أَيۡمَٰنُكُمۡۗ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ مُخۡتَالٗا فَخُورًا","578":"وَإِذَا حُيِّيتُم بِتَحِيَّةٖ فَحَيُّواْ بِأَحۡسَنَ مِنۡهَآ أَوۡ رُدُّوهَآۗ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءٍ حَسِيبًا","606":"۞ لَّا خَيۡرَ فِي كَثِيرٖ مِّن نَّجۡوَىٰهُمۡ إِلَّا مَنۡ أَمَرَ بِصَدَقَةٍ أَوۡ مَعۡرُوفٍ أَوۡ إِصۡلَٰحِۭ بَيۡنَ ٱلنَّاسِۚ وَمَن يَفۡعَلۡ ذَٰلِكَ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ فَسَوۡفَ نُؤۡتِيهِ أَجۡرًا عَظِيمٗا","627":"۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّٰمِينَ بِٱلۡقِسۡطِ شُهَدَآءَ لِلَّهِ وَلَوۡ عَلَىٰٓ أَنفُسِكُمۡ أَوِ ٱلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَۚ إِن يَكُنۡ غَنِيًّا أَوۡ فَقِيرٗا فَٱللَّهُ أَوۡلَىٰ بِهِمَاۖ فَلَا تَتَّبِعُواْ ٱلۡهَوَىٰٓ أَن تَعۡدِلُواْۚ وَإِن تَلۡوُۥٓاْ أَوۡ تُعۡرِضُواْ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا","670":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُحِلُّواْ شَعَٰٓئِرَ ٱللَّهِ وَلَا ٱلشَّهۡرَ ٱلۡحَرَامَ وَلَا ٱلۡهَدۡيَ وَلَا ٱلۡقَلَٰٓئِدَ وَلَآ ءَآمِّينَ ٱلۡبَيۡتَ ٱلۡحَرَامَ يَبۡتَغُونَ فَضۡلٗا مِّن رَّبِّهِمۡ وَرِضۡوَٰنٗاۚ وَإِذَا حَلَلۡتُمۡ فَٱصۡطَادُواْۚ وَلَا يَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ أَن صَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ أَن تَعۡتَدُواْۘ وَتَعَاوَنُواْ عَلَى ٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَلَا تَعَاوَنُواْ عَلَى ٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِۚ وَٱتَّقُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ","676":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّٰمِينَ لِلَّهِ شُهَدَآءَ بِٱلۡقِسۡطِۖ وَلَا يَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ عَلَىٰٓ أَلَّا تَعۡدِلُواْۚ ٱعۡدِلُواْ هُوَ أَقۡرَبُ لِلتَّقۡوَىٰۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ","940":"وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ حَتَّىٰ يَبۡلُغَ أَشُدَّهُۥۚ وَأَوۡفُواْ ٱلۡكَيۡلَ وَٱلۡمِيزَانَ بِٱلۡقِسۡطِۖ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۖ وَإِذَا قُلۡتُمۡ فَٱعۡدِلُواْ وَلَوۡ كَانَ ذَا قُرۡبَىٰۖ وَبِعَهۡدِ ٱللَّهِ أَوۡفُواْۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَذَكَّرُونَ","1152":"خُذِ ٱلۡعَفۡوَ وَأۡمُرۡ بِٱلۡعُرۡفِ وَأَعۡرِضۡ عَنِ ٱلۡجَٰهِلِينَ","1186":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَخُونُواْ ٱللَّهَ وَٱلرَّسُولَ وَتَخُونُوٓاْ أَمَٰنَٰتِكُمۡ وَأَنتُمۡ تَعۡلَمُونَ","1217":"وَإِمَّا تَخَافَنَّ مِن قَوۡمٍ خِيَانَةٗ فَٱنۢبِذۡ إِلَيۡهِمۡ عَلَىٰ سَوَآءٍۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡخَآئِنِينَ","1353":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَكُونُواْ مَعَ ٱلصَّٰدِقِينَ","1990":"۞ إِنَّ ٱللَّهَ يَأۡمُرُ بِٱلۡعَدۡلِ وَٱلۡإِحۡسَٰنِ وَإِيتَآيِٕ ذِي ٱلۡقُرۡبَىٰ وَيَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِ وَٱلۡبَغۡيِۚ يَعِظُكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ","1991":"وَأَوۡفُواْ بِعَهۡدِ ٱللَّهِ إِذَا عَٰهَدتُّمۡ وَلَا تَنقُضُواْ ٱلۡأَيۡمَٰنَ بَعۡدَ تَوۡكِيدِهَا وَقَدۡ جَعَلۡتُمُ ٱللَّهَ عَلَيۡكُمۡ كَفِيلًاۚ إِنَّ ٱللَّهَ يَعۡلَمُ مَا تَفۡعَلُونَ","1992":"وَلَا تَكُونُواْ كَٱلَّتِي نَقَضَتۡ غَزۡلَهَا مِنۢ بَعۡدِ قُوَّةٍ أَنكَٰثٗا تَتَّخِذُونَ أَيۡمَٰنَكُمۡ دَخَلَۢا بَيۡنَكُمۡ أَن تَكُونَ أُمَّةٌ هِيَ أَرۡبَىٰ مِنۡ أُمَّةٍۚ إِنَّمَا يَبۡلُوكُمُ ٱللَّهُ بِهِۦۚ وَلَيُبَيِّنَنَّ لَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ مَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ","1993":"وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَكُمۡ أُمَّةٗ وَٰحِدَةٗ وَلَٰكِن يُضِلُّ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۚ وَلَتُسۡـَٔلُنَّ عَمَّا كُنتُمۡ تَعۡمَلُونَ","1994":"وَلَا تَتَّخِذُوٓاْ أَيۡمَٰنَكُمۡ دَخَلَۢا بَيۡنَكُمۡ فَتَزِلَّ قَدَمُۢ بَعۡدَ ثُبُوتِهَا وَتَذُوقُواْ ٱلسُّوٓءَ بِمَا صَدَدتُّمۡ عَن سَبِيلِ ٱللَّهِ وَلَكُمۡ عَذَابٌ عَظِيمٞ","2062":"وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ حَتَّىٰ يَبۡلُغَ أَشُدَّهُۥۚ وَأَوۡفُواْ بِٱلۡعَهۡدِۖ إِنَّ ٱلۡعَهۡدَ كَانَ مَسۡـُٔولٗا","2064":"وَلَا تَقۡفُ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۚ إِنَّ ٱلسَّمۡعَ وَٱلۡبَصَرَ وَٱلۡفُؤَادَ كُلُّ أُوْلَٰٓئِكَ كَانَ عَنۡهُ مَسۡـُٔولٗا","2081":"وَقُل لِّعِبَادِي يَقُولُواْ ٱلَّتِي هِيَ أَحۡسَنُۚ إِنَّ ٱلشَّيۡطَٰنَ يَنزَغُ بَيۡنَهُمۡۚ إِنَّ ٱلشَّيۡطَٰنَ كَانَ لِلۡإِنسَٰنِ عَدُوّٗا مُّبِينٗا","2303":"وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِسۡمَٰعِيلَۚ إِنَّهُۥ كَانَ صَادِقَ ٱلۡوَعۡدِ وَكَانَ رَسُولٗا نَّبِيّٗا","2624":"ذَٰلِكَۖ وَمَن يُعَظِّمۡ حُرُمَٰتِ ٱللَّهِ فَهُوَ خَيۡرٞ لَّهُۥ عِندَ رَبِّهِۦۗ وَأُحِلَّتۡ لَكُمُ ٱلۡأَنۡعَٰمُ إِلَّا مَا يُتۡلَىٰ عَلَيۡكُمۡۖ فَٱجۡتَنِبُواْ ٱلرِّجۡسَ مِنَ ٱلۡأَوۡثَٰنِ وَٱجۡتَنِبُواْ قَوۡلَ ٱلزُّورِ","2768":"ٱدۡفَعۡ بِٱلَّتِي هِيَ أَحۡسَنُ ٱلسَّيِّئَةَۚ نَحۡنُ أَعۡلَمُ بِمَا يَصِفُونَ","2817":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَدۡخُلُواْ بُيُوتًا غَيۡرَ بُيُوتِكُمۡ حَتَّىٰ تَسۡتَأۡنِسُواْ وَتُسَلِّمُواْ عَلَىٰٓ أَهۡلِهَاۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ","2818":"فَإِن لَّمۡ تَجِدُواْ فِيهَآ أَحَدٗا فَلَا تَدۡخُلُوهَا حَتَّىٰ يُؤۡذَنَ لَكُمۡۖ وَإِن قِيلَ لَكُمُ ٱرۡجِعُواْ فَٱرۡجِعُواْۖ هُوَ أَزۡكَىٰ لَكُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ عَلِيمٞ","2819":"لَّيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَدۡخُلُواْ بُيُوتًا غَيۡرَ مَسۡكُونَةٖ فِيهَا مَتَٰعٞ لَّكُمۡۚ وَٱللَّهُ يَعۡلَمُ مَا تُبۡدُونَ وَمَا تَكۡتُمُونَ","2917":"وَعِبَادُ ٱلرَّحۡمَٰنِ ٱلَّذِينَ يَمۡشُونَ عَلَى ٱلۡأَرۡضِ هَوۡنٗا وَإِذَا خَاطَبَهُمُ ٱلۡجَٰهِلُونَ قَالُواْ سَلَٰمٗا","2926":"وَٱلَّذِينَ لَا يَشۡهَدُونَ ٱلزُّورَ وَإِذَا مَرُّواْ بِٱللَّغۡوِ مَرُّواْ كِرَامٗا","3486":"وَلَا تُصَعِّرۡ خَدَّكَ لِلنَّاسِ وَلَا تَمۡشِ فِي ٱلۡأَرۡضِ مَرَحًاۖ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ مُخۡتَالٖ فَخُورٖ","3487":"وَٱقۡصِدۡ فِي مَشۡيِكَ وَٱغۡضُضۡ مِن صَوۡتِكَۚ إِنَّ أَنكَرَ ٱلۡأَصۡوَٰتِ لَصَوۡتُ ٱلۡحَمِيرِ","3585":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَدۡخُلُواْ بُيُوتَ ٱلنَّبِيِّ إِلَّآ أَن يُؤۡذَنَ لَكُمۡ إِلَىٰ طَعَامٍ غَيۡرَ نَٰظِرِينَ إِنَىٰهُ وَلَٰكِنۡ إِذَا دُعِيتُمۡ فَٱدۡخُلُواْ فَإِذَا طَعِمۡتُمۡ فَٱنتَشِرُواْ وَلَا مُسۡتَـٔۡنِسِينَ لِحَدِيثٍۚ إِنَّ ذَٰلِكُمۡ كَانَ يُؤۡذِي ٱلنَّبِيَّ فَيَسۡتَحۡيِۦ مِنكُمۡۖ وَٱللَّهُ لَا يَسۡتَحۡيِۦ مِنَ ٱلۡحَقِّۚ وَإِذَا سَأَلۡتُمُوهُنَّ مَتَٰعٗا فَسۡـَٔلُوهُنَّ مِن وَرَآءِ حِجَابٖۚ ذَٰلِكُمۡ أَطۡهَرُ لِقُلُوبِكُمۡ وَقُلُوبِهِنَّۚ وَمَا كَانَ لَكُمۡ أَن تُؤۡذُواْ رَسُولَ ٱللَّهِ وَلَآ أَن تَنكِحُوٓاْ أَزۡوَٰجَهُۥ مِنۢ بَعۡدِهِۦٓ أَبَدًاۚ إِنَّ ذَٰلِكُمۡ كَانَ عِندَ ٱللَّهِ عَظِيمًا","3602":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَقُولُواْ قَوۡلٗا سَدِيدٗا","3603":"يُصۡلِحۡ لَكُمۡ أَعۡمَٰلَكُمۡ وَيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۗ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ فَقَدۡ فَازَ فَوۡزًا عَظِيمًا","4251":"وَلَا تَسۡتَوِي ٱلۡحَسَنَةُ وَلَا ٱلسَّيِّئَةُۚ ٱدۡفَعۡ بِٱلَّتِي هِيَ أَحۡسَنُ فَإِذَا ٱلَّذِي بَيۡنَكَ وَبَيۡنَهُۥ عَدَٰوَةٞ كَأَنَّهُۥ وَلِيٌّ حَمِيمٞ","4252":"وَمَا يُلَقَّىٰهَآ إِلَّا ٱلَّذِينَ صَبَرُواْ وَمَا يُلَقَّىٰهَآ إِلَّا ذُو حَظٍّ عَظِيمٖ","4311":"وَجَزَٰٓؤُاْ سَيِّئَةٖ سَيِّئَةٞ مِّثۡلُهَاۖ فَمَنۡ عَفَا وَأَصۡلَحَ فَأَجۡرُهُۥ عَلَى ٱللَّهِۚ إِنَّهُۥ لَا يُحِبُّ ٱلظَّٰلِمِينَ","4617":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن جَآءَكُمۡ فَاسِقُۢ بِنَبَإٖ فَتَبَيَّنُوٓاْ أَن تُصِيبُواْ قَوۡمَۢا بِجَهَٰلَةٖ فَتُصۡبِحُواْ عَلَىٰ مَا فَعَلۡتُمۡ نَٰدِمِينَ","4620":"وَإِن طَآئِفَتَانِ مِنَ ٱلۡمُؤۡمِنِينَ ٱقۡتَتَلُواْ فَأَصۡلِحُواْ بَيۡنَهُمَاۖ فَإِنۢ بَغَتۡ إِحۡدَىٰهُمَا عَلَى ٱلۡأُخۡرَىٰ فَقَٰتِلُواْ ٱلَّتِي تَبۡغِي حَتَّىٰ تَفِيٓءَ إِلَىٰٓ أَمۡرِ ٱللَّهِۚ فَإِن فَآءَتۡ فَأَصۡلِحُواْ بَيۡنَهُمَا بِٱلۡعَدۡلِ وَأَقۡسِطُوٓاْۖ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ","4621":"إِنَّمَا ٱلۡمُؤۡمِنُونَ إِخۡوَةٞ فَأَصۡلِحُواْ بَيۡنَ أَخَوَيۡكُمۡۚ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُرۡحَمُونَ","4622":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا يَسۡخَرۡ قَوۡمٞ مِّن قَوۡمٍ عَسَىٰٓ أَن يَكُونُواْ خَيۡرٗا مِّنۡهُمۡ وَلَا نِسَآءٞ مِّن نِّسَآءٍ عَسَىٰٓ أَن يَكُنَّ خَيۡرٗا مِّنۡهُنَّۖ وَلَا تَلۡمِزُوٓاْ أَنفُسَكُمۡ وَلَا تَنَابَزُواْ بِٱلۡأَلۡقَٰبِۖ بِئۡسَ ٱلِٱسۡمُ ٱلۡفُسُوقُ بَعۡدَ ٱلۡإِيمَٰنِۚ وَمَن لَّمۡ يَتُبۡ فَأُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ","4623":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱجۡتَنِبُواْ كَثِيرٗا مِّنَ ٱلظَّنِّ إِنَّ بَعۡضَ ٱلظَّنِّ إِثۡمٞۖ وَلَا تَجَسَّسُواْ وَلَا يَغۡتَب بَّعۡضُكُم بَعۡضًاۚ أَيُحِبُّ أَحَدُكُمۡ أَن يَأۡكُلَ لَحۡمَ أَخِيهِ مَيۡتٗا فَكَرِهۡتُمُوهُۚ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ تَوَّابٞ رَّحِيمٞ","5114":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا قِيلَ لَكُمۡ تَفَسَّحُواْ فِي ٱلۡمَجَٰلِسِ فَٱفۡسَحُواْ يَفۡسَحِ ٱللَّهُ لَكُمۡۖ وَإِذَا قِيلَ ٱنشُزُواْ فَٱنشُزُواْ يَرۡفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ دَرَجَٰتٖۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ","5134":"وَٱلَّذِينَ تَبَوَّءُو ٱلدَّارَ وَٱلۡإِيمَٰنَ مِن قَبۡلِهِمۡ يُحِبُّونَ مَنۡ هَاجَرَ إِلَيۡهِمۡ وَلَا يَجِدُونَ فِي صُدُورِهِمۡ حَاجَةٗ مِّمَّآ أُوتُواْ وَيُؤۡثِرُونَ عَلَىٰٓ أَنفُسِهِمۡ وَلَوۡ كَانَ بِهِمۡ خَصَاصَةٞۚ وَمَن يُوقَ شُحَّ نَفۡسِهِۦ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ","5164":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لِمَ تَقُولُونَ مَا لَا تَفۡعَلُونَ","5165":"كَبُرَ مَقۡتًا عِندَ ٱللَّهِ أَن تَقُولُواْ مَا لَا تَفۡعَلُونَ","5218":"فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ أَوۡ فَارِقُوهُنَّ بِمَعۡرُوفٖ وَأَشۡهِدُواْ ذَوَيۡ عَدۡلٖ مِّنكُمۡ وَأَقِيمُواْ ٱلشَّهَٰدَةَ لِلَّهِۚ ذَٰلِكُمۡ يُوعَظُ بِهِۦ مَن كَانَ يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مَخۡرَجٗا","6087":"فَأَمَّا ٱلۡيَتِيمَ فَلَا تَقۡهَرۡ","6088":"وَأَمَّا ٱلسَّآئِلَ فَلَا تَنۡهَرۡ","6200":"فَوَيۡلٞ لِّلۡمُصَلِّينَ","6201":"ٱلَّذِينَ هُمۡ عَن صَلَاتِهِمۡ سَاهُونَ","6202":"ٱلَّذِينَ هُمۡ يُرَآءُونَ","6203":"وَيَمۡنَعُونَ ٱلۡمَاعُونَ"},"nay":56,"nq":57};
